export const BODY: string = "\n<p>آپ کی اسکرین پر ہر رنگ کے کئی نام ہیں۔ وہی نیلا #2563EB، rgb(37, 99, 235)، یا hsl(221, 83%, 53%) ہو سکتا ہے، اور تینوں بالکل ایک ہی پکسل بیان کرتے ہیں۔</p>\n<p>یہ اوورلیپ شروع کرنے والوں کو الجھاتا ہے۔ اگر کوڈ ایک دوسرے کی جگہ استعمال ہو سکتے ہیں تو چار فارمیٹ کیوں ہیں، اور آپ کو اصل میں کون سا استعمال کرنا چاہیے؟</p>\n<p>یہ مضمون HEX، RGB، HSL، اور CMYK کو ساتھ ساتھ بتاتا ہے: ہر ایک کا کیا مطلب ہے، یہ کہاں استعمال ہوتا ہے، اور اپنے کام کے لیے درست فارمیٹ کیسے چنیں۔</p>\n<h2 id=\"why-multiple-formats-exist\">کئی رنگ فارمیٹ کیوں ہیں؟</h2>\n<p>مختلف کاموں کو رنگ کی مختلف تفصیل چاہیے ہوتی ہے۔ ویب ڈویلپر CSS میں چسپاں کرنے کے لیے مختصر کوڈ چاہتا ہے، جبکہ ڈیزائنر رنگ کو ہیو کے طور پر بیان کرنا چاہتا ہے۔</p>\n<p>HEX کمپیوٹر رنگ محفوظ کرنے کے طریقے سے بڑھا: تین بائٹ، ہر ایک سرخ، سبز، اور نیلے کے لیے، چھ ہیکساڈیسیمل ہندسوں کے طور پر لکھے گئے۔ یہ کمپیکٹ اور کاپی کے لیے دوستانہ ہے۔</p>\n<p>RGB اسکرین رنگ پیدا کرنے کے طریقے سے بڑھا: سرخ، سبز، اور نیلے روشنی کے تین لیمپ، ہر ایک کی شدت 0 سے 255 تک۔ یہ سیدھا اور پڑھنے کے قابل ہے۔</p>\n<p>HSL انسان رنگ کے بارے میں سوچنے کے طریقے سے بڑھا: پہلے ہیو، پھر یہ کتنا بھرپور ہے، پھر یہ کتنا ہلکا یا تاریک ہے۔ یہ زیادہ تر ڈیزائن ٹولز کے سلائیڈر سے میل کھاتا ہے۔</p>\n<h2 id=\"hex-explained\">HEX کی وضاحت</h2>\n<p>HEX کوڈ ہیش نشان سے شروع ہوتا ہے جس کے بعد چھ ہیکساڈیسیمل ہندسے ہوتے ہیں، جیسے #2563EB۔ پہلے دو ہندسے سرخ، اگلے دو سبز، اور آخری دو نیلے ہیں۔</p>\n<p>ہر جوڑا ہیکساڈیسیمل میں 00 سے FF تک ہوتا ہے، جو اعشاریہ میں 0 سے 255 کے برابر ہے۔ اس لیے #FF0000 خالص سرخ ہے، #00FF00 خالص سبز ہے، اور #000000 سیاہ ہے۔</p>\n<p>HEX CSS اور زیادہ تر ڈیزائن ٹولز کے لیے ڈیفالٹ فارمیٹ ہے۔ یہ مختصر ہے، یہ اسٹائل شیٹ میں صاف چسپاں ہوتا ہے، اور رنگ پکر سے کاپی کرنا آسان ہے۔</p>\n<p>کچھ کوڈ مختصر ہو سکتے ہیں: #336699 #369 بن جاتا ہے، کیونکہ ہر جوڑے میں دو ایک جیسے ہندسے ہوتے ہیں۔ مختصر شکل کا ایک ہی رنگ مطلب ہوتا ہے، مگر زیادہ تر ٹول مکمل شکل دکھاتے ہیں۔</p>\n<h2 id=\"rgb-explained\">RGB کی وضاحت</h2>\n<p>RGB وہی تین اقدار اعشاریہ نمبروں کے طور پر لکھتا ہے، جیسے rgb(37, 99, 235)۔ ہر نمبر 0 سے چلتا ہے، جس کا مطلب اس روشنی میں سے کوئی نہیں، 255 تک، جس کا مطلب مکمل طاقت ہے۔</p>\n<p>RGB اسکرین کیا کرتی ہے اس کی سب سے لفظی تفصیل ہے۔ یہ بالکل بتاتا ہے کہ کتنی سرخ، سبز، اور نیلی روشنی ملانی ہے، اسی لیے تصویر ایڈیٹر اور کیمرے اسے استعمال کرتے ہیں۔</p>\n<p>RGB RGBA سے شفافیت بھی سپورٹ کرتا ہے، جو مبہم پن کے لیے چوتھا نمبر بڑھاتا ہے۔ rgba(37, 99, 235, 0.5) آدھی مبہم پن پر وہی نیلا ہے۔</p>\n<p>زیادہ تر دفتری سافٹ ویئر اور دستاویز ٹول RGB اقدار مانگتے ہیں۔ جب برانڈ گائیڈ رنگ کو تین نمبروں کے طور پر درج کرے تو یہ عام طور پر RGB شکل دے رہا ہوتا ہے۔</p>\n<h2 id=\"hsl-explained\">HSL کی وضاحت</h2>\n<p>HSL رنگ کو تین مختلف خیالات سے بیان کرتا ہے: ہیو، سیچوریشن، اور ہلکی پن۔ عام قدر hsl(221, 83%, 53%) جیسی لگتی ہے۔</p>\n<p>ہیو رنگ پہیے پر زاویہ ہے، 0 سے 360 ڈگری تک۔ سرخ 0 کے قریب بیٹھتا ہے، سبز 120 کے قریب، نیلا 240 کے قریب، اور پہیہ 360 پر سرخ پر واپس آتا ہے۔</p>\n<p>سیچوریشن فیصد ہے: 0 فیصد سرمئی ہے، 100 فیصد ہیو کا سب سے روشن ورژن ہے۔ ہلکی پن بھی فیصد ہے: 0 سیاہ ہے، 50 خالص ہیو ہے۔</p>\n<p>HSL تب چمکتا ہے جب آپ کو ایک رنگ کی مختلف حالتیں چاہیے ہوں۔ ہلکی بٹن ہوور حالت بنانے کے لیے ہیو اور سیچوریشن رکھیں اور ہلکی پن بڑھائیں۔ یہ ایک چھوٹی ایڈٹ ہے۔</p>\n<h2 id=\"cmyk-explained\">CMYK کی وضاحت</h2>\n<p>CMYK رنگ کو کاغذ پر سیاہی کے طور پر بیان کرتا ہے: سیان، میجنٹا، پیلا، اور سیاہ، ہر ایک فیصد کے طور پر۔ عام قدر cmyk(84%, 58%, 0%, 8%) ہے۔</p>\n<p>پرنٹر سیاہی کو گھٹا کر ملاتے ہیں، جو اسکرین کے برعکس ہے۔ جہاں اسکرین سفید تک پہنچنے کے لیے روشنی بڑھاتی ہے، وہاں پرنٹر سفید کاغذ سے شروع کرتا ہے اور سیاہی بڑھاتا ہے تاکہ تاریک ہو۔</p>\n<p>یہ فرق کا مطلب ہے کہ کچھ اسکرین رنگ بالکل پرنٹ نہیں ہو سکتے۔ بہت روشن نیلے اور سبز اکثر سیاہی کی حد سے باہر ہوتے ہیں، اس لیے پرنٹ شدہ نتیجہ مدھم لگتا ہے۔</p>\n<p>امیج کلر پکر سے دکھائی گئی CMYK اقدار اسکرین رنگ سے حساب شدہ تخمینہ ہیں۔ انہیں پرنٹ گفتگو کے لیے نقطہ آغاز سمجھیں، درست قدر نہیں۔</p>\n<h2 id=\"hex-vs-rgb\">HEX بمقابلہ RGB: کون سا استعمال کریں؟</h2>\n<p>HEX اور RGB ایک ہی رنگ کو ایک ہی تین نمبروں سے بیان کرتے ہیں، صرف مختلف لکھے گئے۔ #2563EB اور rgb(37, 99, 235) دو نشان میں ایک ہی نیلا ہیں۔</p>\n<p>CSS اور شیئر کرنے کے لیے HEX چنیں۔ یہ مختصر ہے، یہ اسٹائل شیٹ میں روایت ہے، اور یہ ڈیزائن ٹول اور چیٹ پیغامات میں صاف کاپی ہوتا ہے۔</p>\n<p>RGB چنیں جب ٹول تین نمبر مانگے، یا جب آپ کو شفافیت چاہیے ہو۔ RGBA CSS میں نیم شفاف رنگ لکھنے کا معیاری طریقہ ہے۔</p>\n<p>ان کے درمیان تبدیلی سادہ حساب ہے۔ ہر HEX جوڑا ایک اعشاریہ نمبر میں بدلتا ہے، اس لیے #25 37 بن جاتا ہے، #63 99 بن جاتا ہے، اور #EB 235 بن جاتا ہے۔</p>\n<h2 id=\"hsl-vs-hex-rgb\">HSL بمقابلہ HEX اور RGB: HSL کب جیتتا ہے</h2>\n<p>HSL تب جیتتا ہے جب آپ ایک رنگ کا نام دینے کے بجائے رنگ سسٹم ڈیزائن کر رہے ہوں۔ HSL میں بنائی گئی پیلیٹ مربوط رہتی ہے کیونکہ ہیو مقرر رہتا ہے جبکہ ہلکی پن بدلتی ہے۔</p>\n<p>تین حالتوں والے بٹن پر غور کریں: عام، ہوور، اور غیر فعال۔ HSL میں آپ ہیو 221 اور سیچوریشن 83 فیصد رکھتے ہیں، پھر ہلکی پن کو 53، 45، اور 70 فیصد پر سیٹ کرتے ہیں۔</p>\n<p>HEX میں وہی کرنا تین غیر متعلقہ کوڈ ایجاد کرنا ہے۔ وہ ٹھیک لگ سکتے ہیں، مگر کوڈ میں کچھ نہیں بتاتا کہ وہ ساتھ ہیں۔</p>\n<p>بہت سے ڈیزائن ٹول اب HSL ان پٹ سیدھا قبول کرتے ہیں، اور CSS اسے مقامی طور پر سپورٹ کرتا ہے۔ اگر آپ کے ورک فلو میں شیڈ اور ٹنٹ شامل ہوں تو HSL وہ فارمیٹ ہے جو انہیں منظم رکھتا ہے۔</p>\n<h2 id=\"converting-between-formats\">فارمیٹ کے درمیان تبدیلی</h2>\n<p>آپ کو شاذ و نادر ہی ہاتھ سے بدلنے کی ضرورت ہوتی ہے، کیونکہ کلر پکر تمام فارمیٹ ایک ساتھ دکھاتا ہے۔ پھر بھی تبدیلی کو سمجھنا نمبروں پر بھروسہ کرنے میں مدد کرتا ہے۔</p>\n<p>HEX سے RGB بنیادی تبدیلی ہے: ہیکس ہندسوں کا ہر جوڑا 0 سے 255 تک اعشاریہ بن جاتا ہے۔ FF 255 ہے، 80 128 ہے، اور 00 0 ہے۔</p>\n<p>RGB سے HSL فارمولا ہے، تلاش نہیں۔ یہ تین اقدار میں سے سب سے بڑی اور سب سے چھوٹی تلاش کرتا ہے، ان کے اوسط سے ہلکی پن نکالتا ہے، اور حساب کرتا ہے کہ کون سی قدر ہیو طے کرتی ہے۔</p>\n<p>RGB سے CMYK بھی فارمولا ہے۔ یہ RGB اقدار کو الٹتا ہے، سب سے چھوٹی کو سیاہ کلید کے طور پر تلاش کرتا ہے، پھر باقی کو پیمانہ کرتا ہے۔ اسی لیے CMYK نتیجہ تخمینہ ہے۔</p>\n<h2 id=\"which-format-for-web\">ویب پر کون سا فارمیٹ استعمال کریں؟</h2>\n<p>زیادہ تر ویب سائٹس کے لیے HEX محفوظ ڈیفالٹ ہے۔ یہ مختصر ہے، عالمگیر سپورٹ شدہ ہے، اور ہر ڈویلپر اسے ایک نظر میں پہچانتا ہے۔</p>\n<p>شفافیت چاہیے ہو تو RGBA استعمال کریں۔ نیم شفاف اوورلے یا نرم سایہ 1 سے نیچے مبہم پن والی rgba کے طور پر آسان ترین ہے۔</p>\n<p>منظم شیڈ والا تھیم بناتے وقت HSL استعمال کریں۔ ایک ہیو سے ہلکے اور تاریک مختلف حالتیں بنانے والے ڈیزائن سسٹم HSL میں برقرار رکھنا کہیں آسان ہوتے ہیں۔</p>\n<p>جدید CSS OKLCH جیسے نئے فارمیٹ بھی سپورٹ کرتا ہے، جو رنگ کو زیادہ یکساں بیان کرتے ہیں۔ وہ امید افزا ہیں، مگر HEX، RGB، اور HSL وہ فارمیٹ رہتے ہیں جنہیں ہر ٹول جانتا ہے۔</p>\n<h2 id=\"which-format-for-print\">پرنٹ کے لیے کون سا فارمیٹ استعمال کریں؟</h2>\n<p>پرنٹ کے لیے CMYK کام کرنے والی زبان ہے۔ پرنٹر سیاہی فیصد میں سوچتے ہیں، اور CMYK میں تیار شدہ فائل پریس پر حیرت سے بچتی ہے۔</p>\n<p>اسکرین رنگ سے شروع کریں، پکر سے CMYK تخمینہ نوٹ کریں، اور پھر پرنٹ شدہ پروف سے تصدیق کریں۔ پروف ہی واحد حقیقی ٹیسٹ ہے۔</p>\n<p>پرنٹ کام کبھی صرف HEX کوڈ اور بغیر CMYK بحث کے نہ بھیجیں۔ پرنٹر اسے بدلے گا، مگر تبدیلی ایسی سیاہی اقدار چن سکتی ہے جو آپ نے نہ چنی ہوں۔</p>\n<p>برانڈ کام کے لیے پرنٹر سے ان کا رنگ پروفائل مانگیں۔ پروفائل اسکرین رنگ کو مخصوص پریس اور کاغذ کے لیے سیاہی سے نقشہ بناتا ہے، اور یہ کسی بھی عمومی فارمولے کو ہراتا ہے۔</p>\n<h2 id=\"which-format-for-design-tools\">ڈیزائن ٹولز میں کون سا فارمیٹ استعمال کریں؟</h2>\n<p>Figma، Photoshop، اور Canva اپنے رنگ فیلڈ میں چسپاں شدہ HEX قبول کرتے ہیں، اس لیے HEX چنے گئے رنگ کو ڈیزائن میں منتقل کرنے کا تیز ترین طریقہ ہے۔</p>\n<p>جب آپ ٹول کے اندر رنگ ایڈجسٹ کریں تو آپ عام طور پر ہیو، سیچوریشن، اور ہلکی پن کے لیے HSL طرز سلائیڈر گھسیٹیں گے۔ ٹول HEX دکھاتا ہے، مگر آپ HSL معنوں میں ایڈٹ کرتے ہیں۔</p>\n<p>برانڈ گائیڈ اکثر تینوں درج کرتے ہیں: ڈویلپروں کے لیے HEX، دستاویزات کے لیے RGB، اور پرنٹ کے لیے CMYK۔ یہ اچھی عادت ہے، کیونکہ ہر سامعین مختلف فارمیٹ استعمال کرتا ہے۔</p>\n<p>اگر آپ <a href=\"/ur/tasveer-se-rang-palette-nikalein/\">image color palette extractor</a> سے پیلیٹ نکالیں تو ایکسپورٹ میں ہر سوئچ کے لیے HEX، RGB، اور HSL شامل ہوتے ہیں، اس لیے آپ کو کبھی کچھ بدلنے کی ضرورت نہیں۔</p>\n<h2 id=\"common-mistakes\">رنگ فارمیٹ کے ساتھ عام غلطیاں</h2>\n<p>سب سے عام غلطی یہ فرض کرنا ہے کہ HEX اور RGB مختلف رنگ ہیں۔ وہ ایک ہی قدر کی دو ہجے ہیں، اس لیے #2563EB اور rgb(37, 99, 235) ہمیشہ میل کھائیں گے۔</p>\n<p>دوسری غلطی CMYK تخمینے کو درست سمجھنا ہے۔ اسکرین سے پرنٹ تبدیلی فارمولا ہے، اور اصل پرنٹ شدہ رنگ پریس، سیاہی، اور کاغذ پر منحصر ہوتا ہے۔</p>\n<p>لوگ یہ بھی بھول جاتے ہیں کہ ہلکی پن چمک نہیں ہے۔ HSL میں ہلکی پن کو 100 فیصد کی طرف بڑھانا رنگ کو سفید کی طرف دھوتا ہے، جبکہ اسے 0 کی طرف کم کرنا اسے سیاہ کی طرف دھکیلتا ہے۔</p>\n<p>آخر میں، رنگوں کا موازنہ مختلف اسکرین پر صرف آنکھ سے نہ کریں۔ دو مانیٹر ایک ہی HEX کوڈ کو مختلف دکھا سکتے ہیں، اس لیے جب درستگی اہمیت رکھے تو نمبروں پر بھروسہ کریں۔</p>\n<h2 id=\"reading-a-color-picker-output\">کلر پکر آؤٹ پٹ پڑھنا</h2>\n<p>جب آپ پکسل کا نمونہ لیں تو پکر ہر فارمیٹ ایک ساتھ دکھاتا ہے۔ HEX کوڈ وہ ہے جسے ویب کام کے لیے کاپی کریں، اور RGB نمبر وہ ہیں جنہیں دستاویزات کے لیے کاپی کریں۔</p>\n<p>HSL اقدار آپ کو بتاتی ہیں کہ رنگ پہیے پر کہاں بیٹھتا ہے اور یہ کتنا روشن ہے۔ 0 یا 360 کے قریب ہیو سرخ ہے، 120 کے قریب سبز ہے، اور 240 کے قریب نیلا ہے۔</p>\n<p>CMYK فیصد آپ کو بتاتے ہیں کہ رنگ کو کتنی سیاہی چاہیے ہو گی۔ زیادہ سیان اور میجنٹا اور بغیر پیلے والا رنگ نیلا ہے، جبکہ زیادہ پیلا اور کچھ میجنٹا والا نارنجی ہے۔</p>\n<p>چاروں کو ایک نظر میں پڑھنا سیکھنے میں مشق لگتی ہے، مگر یہ فائدہ دیتا ہے۔ آپ کوڈ کو دیکھ کر رنگ کی تصویر بنا سکیں گے اس سے پہلے کہ آپ اسے کہیں چسپاں کریں۔</p>\n<h2 id=\"building-a-palette-with-formats\">فارمیٹ میں پیلیٹ بنانا</h2>\n<p>اچھی پیلیٹ ایک فارمیٹ کو سچائی کا ماخذ رکھتی ہے اور باقی کو اس سے نکالتی ہے۔ زیادہ تر ٹیمیں HEX کو ماخذ رکھتی ہیں، کیونکہ یہ وہ فارمیٹ ہے جسے ڈویلپر کوڈ میں چسپاں کرتے ہیں۔</p>\n<p>HEX بنیاد سے HSL میں صرف ہلکی پن بدل کر ہلکے اور تاریک مختلف حالتیں بنائیں۔ یہ ہیو خاندان کو برقرار رکھتا ہے اور پیلیٹ کو مربوط رکھتا ہے۔</p>\n<p>دستاویزات کے لیے RGB اقدار اور پرنٹ کے لیے CMYK تخمینے ریکارڈ کریں۔ چاروں فارمیٹ والا برانڈ گائیڈ ہر ٹیم کی خدمت کرتا ہے بغیر کسی کے بدلنے کے۔</p>\n<p>اپنے چنے گئے رنگوں کو پکر سے CSS ویری ایبل کے طور پر ایکسپورٹ کریں، پھر مختلف حالتوں کو ان کے ساتھ دستاویز کریں۔ اسٹائل شیٹ وہ واحد حوالہ بن جاتی ہے جس پر سب بھروسہ کرتے ہیں۔</p>\n<h2 id=\"hsl-and-accessibility\">HSL اور رسائی: ہلکی پن سے کنٹراسٹ</h2>\n<p>رسائی اصول کنٹراسٹ کی پرواہ کرتے ہیں، اور HSL کنٹراسٹ کے بارے میں سوچنا آسان بناتا ہے۔ ہلکی پن اقدار بہت دور والے دو رنگ عام طور پر کنٹراسٹ چیک پاس کریں گے۔</p>\n<p>ہلکے پس منظر پر تاریک متن پر غور کریں۔ اگر متن کی ہلکی پن 15 فیصد کے قریب ہو اور پس منظر 95 فیصد کے قریب بیٹھے تو فرق بڑا ہے اور متن پڑھنے کے قابل ہو گا۔</p>\n<p>وہی منطق ڈارک موڈ کے لیے الٹا لاگو ہوتی ہے۔ 10 فیصد ہلکی پن والے تاریک پس منظر پر 90 فیصد ہلکی پن والا ہلکا متن وہی بڑا فرق دیتا ہے، اور وہی کنٹراسٹ۔</p>\n<p>HSL آپ کو ناکام مجموعے کو اس کی شخصیت بدلے بغیر ٹھیک کرنے میں بھی مدد کرتا ہے۔ اگر رنگین بٹن کنٹراسٹ چیک ناکام کرے تو اس کی ہلکی پن کو دس پوائنٹ کم کریں اور دوبارہ ٹیسٹ کریں۔</p>\n<p>یہ نیا HEX کوڈ اندازے سے کہیں آسان ہے۔ HEX میں رنگ کا تاریک ورژن ہندسوں کا نیا سیٹ ہے جس کا اصل سے کوئی نظر آنے والا تعلق نہیں، اس لیے ہر کوشش اندازہ ہے۔</p>\n<p>جب آپ ڈیزائن کا آڈٹ کریں تو اس کے کلیدی رنگوں کو HSL میں بدلیں اور انہیں ہلکی پن سے ترتیب دیں۔ ترتیب شدہ فہرست ایک نظر میں دکھاتی ہے کہ آپ کا متن، پس منظر، اور ایکسینٹ کنٹراسٹ پاس کرتے ہیں یا نہیں۔</p>\n<p>یاد رکھیں کہ ہیو اور سیچوریشن اکیلے کنٹراسٹ کو بمشکل متاثر کرتے ہیں۔ روشن سرخ اور روشن سبز کی ہلکی پن تقریباً ایک جیسی ہو سکتی ہے، اسی لیے رنگ اندھے دیکھنے والے انہیں الگ نہیں بتا سکتے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: فارمیٹ چیٹ شیٹ</h2>\n<p>HEX ہیش کے بعد چھ ہندسے ہیں، جیسے #2563EB۔ اسے CSS میں، ڈیزائن ٹولز میں، اور جب بھی آپ رنگ کو تحریر میں شیئر کریں استعمال کریں۔</p>\n<p>RGB 0 سے 255 تک تین نمبر ہیں، جیسے rgb(37, 99, 235)۔ اسے دستاویزات میں، دفتری سافٹ ویئر میں، اور جب آپ کو RGBA سے شفافیت چاہیے ہو استعمال کریں۔</p>\n<p>HSL ہیو زاویہ اور سیچوریشن اور ہلکی پن فیصد ہیں، جیسے hsl(221, 83%, 53%)۔ اسے شیڈ، ٹنٹ، اور تھیم مختلف حالتیں بناتے وقت استعمال کریں۔</p>\n<p>CMYK پرنٹ کے لیے چار سیاہی فیصد ہیں۔ اسے پرنٹ شدہ کام کے لیے نقطہ آغاز تخمینے کے طور پر استعمال کریں، اور ہمیشہ پروف سے تصدیق کریں۔ عملی طرف کے لیے <a href=\"/ur/blog/tasveer-color-picker-rehnumai/\">Image Color Picker: Complete Guide</a> دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ویب سائٹ رنگوں کے لیے HEX یا RGB بہتر ہے؟","answer":"رنگ کے لحاظ سے کوئی بہتر نہیں ہے، کیونکہ وہ ایک ہی قدر بیان کرتے ہیں۔ HEX مختصر ہے اور اسٹائل شیٹ میں روایت ہے، اس لیے زیادہ تر ڈویلپر اسے ترجیح دیتے ہیں۔ RGB بہتر ہوتا ہے جب آپ کو شفافیت چاہیے ہو۔"},{"question":"میرا برانڈ رنگ پرنٹ میں اسکرین سے مختلف کیوں لگتا ہے؟","answer":"اسکرین روشنی سے رنگ بناتی ہیں اور پرنٹر سیاہی سے رنگ بناتے ہیں، اور دونوں سسٹم مختلف حدیں پورا کرتے ہیں۔ روشن اسکرین نیلے اور سبز اکثر سیاہی کی دوبارہ پیدا کرنے کی حد سے باہر ہوتے ہیں۔ پکر سے CMYK قدر نقطہ آغاز ہے، حتمی جواب نہیں۔"},{"question":"کیا میں ٹول کے بغیر HEX کوڈ کو HSL میں بدل سکتا ہوں؟","answer":"ہاں، مگر اس میں دو قدم لگتے ہیں: پہلے HEX کو RGB میں بدلیں، پھر RGB-to-HSL فارمولا لگائیں۔ پکر دونوں قدم فوراً کرتا ہے اور ہر فارمیٹ ایک ساتھ دکھاتا ہے۔ ایک بار کی تبدیلی کے لیے کوئی بھی آن لائن کنورٹر کام کرتا ہے۔"},{"question":"HSL میں ہیو نمبر کا اصل میں کیا مطلب ہے؟","answer":"ہیو رنگ پہیے پر 0 سے 360 ڈگری تک زاویہ ہے۔ سرخ 0 کے قریب ہے، پیلا 60 کے قریب، سبز 120 کے قریب، سیان 180 کے قریب، نیلا 240 کے قریب، اور میجنٹا 300 کے قریب۔ 30 ڈگری کے فاصلے والے دو رنگ ایک جیسے لگتے ہیں۔"},{"question":"کیا مجھے ویب سائٹ یا سوشل میڈیا گرافک کے لیے CMYK اقدار چاہیے؟","answer":"نہیں۔ ویب سائٹس، ایپس، اور سوشل گرافکس سب اسکرین میڈیا ہیں، اس لیے HEX، RGB، یا HSL کافی ہے۔ CMYK صرف تب اہمیت رکھتا ہے جب سیاہی کاغذ کو چھوئے۔ CMYK تخمینہ فائل پر رکھیں اگر وہی برانڈ رنگ کبھی پرنٹ ہو۔"},{"question":"کچھ HEX کوڈ میں صرف تین ہندسے کیوں ہوتے ہیں؟","answer":"تین ہندسوں والا HEX کوڈ چھ ہندسوں والے کوڈ کا مختصر ہے جہاں ہر جوڑے میں دو ایک جیسے ہندسے ہوتے ہیں۔ #369 کا مطلب #336699 ہے، کیونکہ 3 دوگنا ہو کر 33، 6 دوگنا ہو کر 66، اور 9 دوگنا ہو کر 99 بن جاتا ہے۔ ہر چھ ہندسوں والا کوڈ مختصر نہیں ہو سکتا۔"}];
